{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Ensure every security group and rule has a description",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "The security group rules lack descriptions, which makes it harder to understand their purpose and audit them effectively."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Security group allows ingress from 0.0.0.0/0",
      "resource": "aws_security_group.vault",
      "severity": "HIGH",
      "explanation": "Allowing ingress from 0.0.0.0/0 exposes the resource to the entire internet, which increases the risk of unauthorized access."
    }
  ],
  "patched_code": "resource "aws_security_group" "vault" {
  name        = "vault"
  description = "Ingress for Vault"
  vpc_id      = aws_vpc.my_vpc.id

  dynamic "ingress" {
    iterator = port
    for_each = var.ingress_ports
    content {
      from_port   = port.value
      to_port     = port.value
      protocol    = "tcp"
      cidr_blocks = var.allowed_cidr_blocks
      description = "Ingress rule for port ${port.value}"
    }
  }
}

variable "allowed_cidr_blocks" {
  description = "List of allowed CIDR blocks for ingress"
  type        = list(string)
  default     = ["192.168.0.0/16"]
}",
  "fix_summary": "Added descriptions to the security group rules for better auditing and replaced the hardcoded 0.0.0.0/0 with a variable for allowed CIDR blocks, defaulting to a private network range."
}
